WITH blacklist AS (SELECT DISTINCT "#varchar_id" account_id FROM user_result_cluster_23 WHERE cluster_name IN ('internal_users','is_water','is_water_mod','suspicious_ip')),
returned AS (SELECT DISTINCT COALESCE(v.fc_sdk_common.lcx_id,v.sdkcommon.lcx_id,v."#account_id") account_id FROM ta.v_event_23 v LEFT JOIN blacklist b ON COALESCE(v.fc_sdk_common.lcx_id,v.sdkcommon.lcx_id,v."#account_id")=b.account_id WHERE v."$part_event"='hero_add' AND CAST(v.hero_id AS INTEGER)=136 AND v.reason='角色返回模块' AND v."$part_date" BETWEEN '2026-07-29' AND '2026-08-04' AND b.account_id IS NULL),
holders AS (SELECT account_id,card_level,awaken_count,talent_count FROM (SELECT COALESCE(v.fc_sdk_common.lcx_id,v.sdkcommon.lcx_id,v."#account_id") account_id,CAST(v.card_level AS INTEGER) card_level,CARDINALITY(v.card_awake) awaken_count,CARDINALITY(FILTER(v.card_talent_slot,x->x<>'0' AND x<>'')) talent_count,ROW_NUMBER() OVER(PARTITION BY COALESCE(v.fc_sdk_common.lcx_id,v.sdkcommon.lcx_id,v."#account_id") ORDER BY CAST(v."#event_time" AS timestamp(3)) DESC) rn FROM ta.v_event_23 v JOIN returned r ON COALESCE(v.fc_sdk_common.lcx_id,v.sdkcommon.lcx_id,v."#account_id")=r.account_id LEFT JOIN blacklist b ON COALESCE(v.fc_sdk_common.lcx_id,v.sdkcommon.lcx_id,v."#account_id")=b.account_id WHERE v."$part_event"='daily_role_card_snapshot' AND CAST(v.card_id AS INTEGER)=136 AND v."$part_date" BETWEEN '2026-07-29' AND '2026-08-04' AND b.account_id IS NULL) x WHERE rn=1),
wallet AS (SELECT CAST(lcxtransactionid AS VARCHAR) transaction_id,MAX(ABS(CAST(freeamount AS DOUBLE))) freeamount FROM ta.v_event_16 WHERE "$part_event"='LCX_WALLET_SPEND_TRANSACTION' AND "$part_date" BETWEEN '2026-07-29' AND '2026-08-04' GROUP BY 1),
revenue AS (SELECT h.account_id,SUM((CAST(JSON_EXTRACT_SCALAR(CAST(v.payload AS JSON),'$.curamt') AS DOUBLE)-COALESCE(w.freeamount,0))/COALESCE(x.exchange,1)) revenue_usd FROM holders h LEFT JOIN ta.v_event_23 v ON v."$part_event"='PURCHASE' AND v."$part_date" BETWEEN '2026-07-29' AND '2026-08-04' AND COALESCE(v.fc_sdk_common.lcx_id,v.sdkcommon.lcx_id,v."#account_id")=h.account_id AND COALESCE(CAST(JSON_EXTRACT_SCALAR(CAST(v.payload AS JSON),'$.validationtype') AS VARCHAR),'')<>'SANDBOX_RECEIPT' LEFT JOIN wallet w ON CAST(JSON_EXTRACT_SCALAR(CAST(v.payload AS JSON),'$.purchaseid') AS VARCHAR)=w.transaction_id LEFT JOIN ta_dim.ta_exchange x ON v."$part_date"=x.ex_date AND JSON_EXTRACT_SCALAR(CAST(v.payload AS JSON),'$.cur')=x.currency GROUP BY 1),
balance_raw AS (SELECT h.account_id,CAST(v.id AS INTEGER) resource_id,GREATEST(MAX_BY(CAST(v.after AS DOUBLE),CAST(v."#event_time" AS timestamp(3))),0) balance FROM holders h JOIN ta.v_event_23 v ON v."$part_event"='resource_change' AND v."$part_date" BETWEEN '2026-06-24' AND '2026-07-28' AND COALESCE(v.fc_sdk_common.lcx_id,v.sdkcommon.lcx_id,v."#account_id")=h.account_id AND CAST(v.id AS INTEGER) IN (3,8,10) GROUP BY 1,2),
base AS (SELECT h.*,COALESCE(r.revenue_usd,0) revenue_usd,COALESCE(MAX(CASE WHEN b.resource_id=10 THEN b.balance END),0) ticket_balance,COALESCE(MAX(CASE WHEN b.resource_id=3 THEN b.balance END),0)+COALESCE(MAX(CASE WHEN b.resource_id=8 THEN b.balance END),0) star_balance FROM holders h LEFT JOIN revenue r ON h.account_id=r.account_id LEFT JOIN balance_raw b ON h.account_id=b.account_id GROUP BY 1,2,3,4,5)
SELECT '西索返还' event_name,COUNT(*) holders,COUNT_IF(revenue_usd>0) payers,ROUND(SUM(revenue_usd),2) revenue_usd,ROUND(AVG(revenue_usd),2) arpu_usd,ROUND(SUM(revenue_usd)/NULLIF(COUNT_IF(revenue_usd>0),0),2) arppu_usd,ROUND(AVG(ticket_balance),2) avg_ticket,ROUND(AVG(star_balance),2) avg_star,ROUND(AVG(ticket_balance+star_balance/150.0),2) avg_potential_draws,ROUND(CAST(COUNT_IF(ticket_balance+star_balance/150.0>=40) AS DOUBLE)/COUNT(*),4) stock_40_rate,ROUND(CAST(COUNT_IF(card_level=10) AS DOUBLE)/COUNT(*),4) level10_rate,ROUND(CAST(COUNT_IF(awaken_count>=1) AS DOUBLE)/COUNT(*),4) awaken1_rate,ROUND(CAST(COUNT_IF(awaken_count>=2) AS DOUBLE)/COUNT(*),4) awaken2_rate,ROUND(CAST(COUNT_IF(awaken_count>=3) AS DOUBLE)/COUNT(*),4) awaken3_rate,ROUND(CAST(COUNT_IF(talent_count>=4) AS DOUBLE)/COUNT(*),4) talent4_rate FROM base;
